export default function bilinear(o,t){const{rows:n,columns:r,data:a}=o,{rows:l,columns:f,data:s}=t,c=[],e=[],h=[];for(let o=0;o<f;o++){const t=o*(r-1)/(f-1);c[o]=Math.floor(t),e[o]=Math.min(c[o]+1,r-1),h[o]=t-c[o]}for(let o=0;o<l;o++){const t=o*(n-1)/(l-1),i=Math.floor(t)*r,u=Math.min(i+r,(n-1)*r),M=t-Math.floor(t),m=1-M,d=o*f;for(let o=0;o<f;o++){const t=a[i+c[o]],n=a[i+e[o]],r=a[u+c[o]],l=a[u+e[o]],f=1-h[o];s[d+o]=(t*f+n*h[o])*m+(r*f+l*h[o])*M}}return s}